{
  "county_id": "HVA03",
  "actions": [
    {
      "action_id": "pathway-timestamps",
      "action": "Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "The brief says the earliest stage where West Uusimaa is clearly worse than the country is early detection, and the Goal 3 indicator on treatment within target times cannot be checked from open data because time from referral to diagnosis and from diagnosis to first treatment is not published by county for any cancer.",
      "owner_role": "FICAN with THL and the Finnish Cancer Registry",
      "indicator": "Share of new cancer cases with all four timestamps recorded",
      "roadmap_measure": "3.2.1"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended cervical cancer screening.",
      "rationale": "Cervical screening participation in West Uusimaa is 72.8% against the 80% target, and the portfolio selects self-sampling for this county with an expected gain of 1.5-4.5 percentage points, closing about 42% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders to colorectal cancer screening and measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in West Uusimaa is 73.4% against the 80% target, and the portfolio selects screening-reminders for this county with an expected gain of 1.5-4.5 percentage points, closing about 45% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support a guaranteed mortality effect for any of these actions: the Finnish gain for self-sampling over a reminder letter is about 3 points, far smaller than the international pooled estimate, no Finnish effect size exists for colorectal screening reminders, and pathway-timestamps models no health effect because it is the measurement that makes other actions accountable."
}

